// Summary rows use counts, while event-by-event task columns remain a proposal.
const leanHome=home;home=function(){return leanHome().replace(/(<div class="desk-tasks">[\s\S]*?<\/div>)<section/,'$1<section').replace(/<small>루미에르 성수 팝업<\/small>/,'').replace(/<small>브랜드사와 검토 중<\/small>/,'').replace(/<small>확정된 시안을 확인하세요<\/small>/,'').replace(/data-go="(operate|review|publish)"/g,'data-open-task-summary')};
const leanShell=shell;shell=function(body){return leanShell(body).replace('<div class="organization-plan"><span>Agency 플랜</span><small>구독 중</small></div>','<div class="organization-plan">Agency 플랜 구독 중</div>').replace('<button class="text-link" data-action="usage">구독·사용량</button>','')};
const summaryBind=bind;bind=function(){summaryBind();app.querySelectorAll('[data-open-task-summary]').forEach(n=>n.onclick=()=>{state.notificationsOpen=true;render()})};render();
const bottomBranding=whitelabel;whitelabel=function(){let h=bottomBranding(),button='<button class="btn " data-action="brand-save">브랜딩 저장</button>';h=h.replace('<p class="mini-label">행사에 별도 문구가 없으면 사용합니다.</p>','').replace('<label for="default-consent">기본 동의 문구</label>','<label for="default-consent">기본 동의 문구</label><p class="mini-label consent-description">행사에 별도 문구가 없으면 사용합니다.</p>');const found=h.match(/<button[^>]*data-action="brand-save"[^>]*>브랜딩 저장<\/button>/);if(found){h=h.replace(found[0],'');h=h.replace('</details></section>','</details><div class="branding-save">'+found[0]+'</div></section>')}return h};render();
